# owner: platform
"""Plain text absence notices for parents."""

from typing import Iterable, List
from rosterkit.models import Mark, Student

def absent_days(student: Student, marks: Iterable[Mark]) -> List:
    """Sorted dates the student was absent. Foreign marks are an error."""
    marks = list(marks)
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(f"mark belongs to {mark.student_id}, not {student.student_id}")
    return sorted(mark.day for mark in marks if mark.status == "absent")

def build_notice(student: Student, marks: Iterable[Mark]) -> str:
    """Short notice naming the student, the days missed and the dates."""
    days = absent_days(student, marks)
    if not days:
        raise ValueError(f"no absences to report for {student.student_id}")
    name = f"{student.first_name} {student.last_name}"
    plural = "day" if len(days) == 1 else "days"
    dates = "\n".join(f"  - {item.isoformat()}" for item in days)
    return f"{name} missed {len(days)} {plural} of school:\n{dates}\n"
